item.aggregated_output:
   1	# Terraform script to deploy AHA Solution
   2	# 1.0 - Initial version 
   3	
   4	# Variables defined below, you can overwrite them using tfvars or imput variables
   5	
   6	data "aws_caller_identity" "current" {}
   7	
   8	provider "aws" {
   9	    region  = var.aha_primary_region
  10	    default_tags {
  11	      tags = "${var.default_tags}"
  12	    }
  13	}
  14	
  15	# Secondary region - provider config
  16	locals {
  17	    secondary_region = "${var.aha_secondary_region == "" ? var.aha_primary_region : var.aha_secondary_region}"
  18	}
  19	
  20	provider "aws" {
  21	    alias   = "secondary_region"
  22	    region  = local.secondary_region
  23	    default_tags {
  24	      tags = "${var.default_tags}"
  25	    }
  26	}
  27	
  28	# Comment below - if needed to use s3_bucket, s3_key for consistency with cf 
  29	locals {
  30	    source_files = ["${path.module}/../../handler.py", "${path.module}/../../messagegenerator.py"]
  31	}
  32	data "archive_file" "lambda_zip" {
  33	    type          = "zip"
  34	    output_path   = "${path.module}/lambda_function.zip"
  35	    source {
  36	      filename = "${basename(local.source_files[0])}"
  37	      content  = file("${local.source_files[0]}")
  38	    }
  39	    source {
  40	      filename = "${basename(local.source_files[1])}"
  41	      content  = file("${local.source_files[1]}")
  42	  }
  43	}
  44	
  45	variable "aha_primary_region" {
  46	    description = "Primary region where AHA solution will be deployed"
  47	    type        = string
  48	    default     = "us-east-1"
  49	}
  50	
  51	variable "aha_secondary_region" {
  52	    description = "Secondary region where AHA solution will be deployed"
  53	    type        = string
  54	    default     = ""
  55	}
  56	
  57	variable "default_tags" {
  58	    description = "Tags used for the AWS resources created by this template"
  59	    type        = map
  60	    default     = {
  61	      Application      = "AHA-Solution"
  62	    }
  63	}
  64	
  65	variable "dynamodbtable" {
  66	    type    = string
  67	    default = "AHA-DynamoDBTable"
  68	}
  69	
  70	variable "AWSOrganizationsEnabled" {
  71	    type = string
  72	    default = "No"
  73	    description = "You can receive both PHD and SHD alerts if you're using AWS Organizations. \n If you are, make sure to enable Organizational Health View: \n (https://docs.aws.amazon.com/health/latest/ug/aggregate-events.html) to \n aggregate all PHD events in your AWS Organization. If not, you can still \n get SHD alerts."
  74	    validation {
  75	      condition = (
  76	        var.AWSOrganizationsEnabled == "Yes" || var.AWSOrganizationsEnabled == "No"
  77	      )
  78	      error_message = "AWSOrganizationsEnabled variable can only accept Yes or No as values."
  79	    }
  80	}
  81	
  82	variable "ManagementAccountRoleArn" {
  83	    type    = string
  84	    default = ""
  85	    description = "Arn of the IAM role in the top-level management account for collecting PHD Events. 'None' if deploying into the top-level management account."
  86	}
  87	
  88	variable "AWSHealthEventType" {
  89	    type = string
  90	    default = "issue | accountNotification | scheduledChange"
  91	    description = "Select the event type that you want AHA to report on. Refer to \n https://docs.aws.amazon.com/health/latest/APIReference/API_EventType.html for more information on EventType."
  92	    validation {
  93	      condition = (
  94	        var.AWSHealthEventType == "issue | accountNotification | scheduledChange" || var.AWSHealthEventType == "issue"
  95	      )
  96	      error_message = "AWSHealthEventType variable can only accept issue | accountNotification | scheduledChange or issue as values."
  97	    }
  98	}
  99	
