 118	variable "EventBusName" {
 119	    type    = string
 120	    default = ""
 121	    description = "This is to ingest alerts into AWS EventBridge. Enter the event bus name if you wish to send the alerts to the AWS EventBridge. Note: By ingesting you wish to send the alerts to the AWS EventBridge. Note: By ingesting these alerts to AWS EventBridge, you can integrate with 35 SaaS vendors such as DataDog/NewRelic/PagerDuty. If you don't prefer to use EventBridge, leave the default (None)."
 122	}
 123	
 124	variable "SlackWebhookURL" {
 125	    type    = string
 126	    default = ""
 127	    description = "Enter the Slack Webhook URL. If you don't prefer to use Slack, leave the default (empty)."
 128	}
 129	
 130	variable "MicrosoftTeamsWebhookURL" {
 131	    type    = string
 132	    default = ""
 133	    description = "Enter Microsoft Teams Webhook URL. If you don't prefer to use MS Teams, leave the default (empty)."
 134	}
 135	
 136	variable "AmazonChimeWebhookURL" {
 137	    type    = string
 138	    default = ""
 139	    description = "Enter the Chime Webhook URL, If you don't prefer to use Amazon Chime, leave the default (empty)."
 140	}
 141	
 142	variable "Regions" {
 143	    type = string
 144	    default = "all regions"
 145	    description = "By default, AHA reports events affecting all AWS regions. \n If you want to report on certain regions you can enter up to 10 in a comma separated format. \n Available Regions: us-east-1,us-east-2,us-west-1,us-west-2,af-south-1,ap-east-1,ap-south-1,ap-northeast-3, \n ap-northeast-2,ap-southeast-1,ap-southeast-2,ap-northeast-1,ca-central-1,eu-central-1,eu-west-1,eu-west-2, \n eu-south-1,eu-south-3,eu-north-1,me-south-1,sa-east-1,global"
 146	}
 147	
 148	variable "EventSearchBack" {
 149	    type = number
 150	    default = "1"
 151	    description = "How far back to search for events in hours. Default is 1 hour"
 152	}
 153	
 154	variable "FromEmail" {
 155	    type = string
 156	    default = "none@domain.com"
 157	    description = "Enter FROM Email Address"
 158	}
 159	
 160	variable "ToEmail" {
 161	    type = string
 162	    default = "none@domain.com"
 163	    description = "Enter email addresses separated by commas (for ex: abc@amazon.com, bcd@amazon.com)"
 164	}
 165	
 166	variable "Subject" {
 167	    type = string
 168	    default = "AWS Health Alert"
 169	    description = "Enter the subject of the email address"
 170	}
