 178	variable "ExcludeAccountIDs" {
 179	    type = string
 180	    default = ""
 181	    description = "If you would like to EXCLUDE any accounts from alerting, enter a .csv filename created with comma-seperated account numbers. Sample AccountIDs file name: aha_account_ids.csv. If not, leave the default empty."
 182	}
 183	
 184	##### Resources for AHA Solution created below.
 185	
 186	# Random id generator
 187	resource "random_string" "resource_code" {
 188	  length  = 8
 189	  special = false
 190	  upper   = false
 191	}
 192	
 193	# S3 buckets creation
 194	resource "aws_s3_bucket" "AHA-S3Bucket-PrimaryRegion" {
 195	    count      = "${var.ExcludeAccountIDs != "" ? 1 : 0}"
 196	    bucket     = "aha-bucket-${var.aha_primary_region}-${random_string.resource_code.result}"
 197	    tags = {
 198	      Name        = "aha-bucket"
 199	    }
 200	}
 201	
 202	resource "aws_s3_bucket_acl" "AHA-S3Bucket-PrimaryRegion" {
 203	    count  = var.ExcludeAccountIDs != "" ? 1 : 0
 204	    bucket = aws_s3_bucket.AHA-S3Bucket-PrimaryRegion[0].id
 205	    acl    = "private"
 206	}
 207	
 208	resource "aws_s3_bucket" "AHA-S3Bucket-SecondaryRegion" {
 209	    count      = "${var.aha_secondary_region != "" && var.ExcludeAccountIDs != "" ? 1 : 0}"
 210	    provider   = aws.secondary_region
 211	    bucket     = "aha-bucket-${var.aha_secondary_region}-${random_string.resource_code.result}"
 212	    tags = {
 213	      Name        = "aha-bucket"
 214	    }
 215	}
 216	
 217	resource "aws_s3_bucket_acl" "AHA-S3Bucket-SecondaryRegion" {
 218	    count  = "${var.aha_secondary_region != "" && var.ExcludeAccountIDs != "" ? 1 : 0}"
 219	    provider   = aws.secondary_region
 220	    bucket = aws_s3_bucket.AHA-S3Bucket-SecondaryRegion[0].id
 221	    acl    = "private"
 222	}
 223	
 224	resource "aws_s3_object" "AHA-S3Object-PrimaryRegion" {
 225	    count      = "${var.ExcludeAccountIDs != "" ? 1 : 0}"
 226	    key        = var.ExcludeAccountIDs
 227	    bucket     = aws_s3_bucket.AHA-S3Bucket-PrimaryRegion[0].bucket
 228	    source     = var.ExcludeAccountIDs
 229	    tags = {
 230	      Name        = "${var.ExcludeAccountIDs}"
 231	    }
 232	}
 233	
 234	resource "aws_s3_object" "AHA-S3Object-SecondaryRegion" {
 235	    count      = "${var.aha_secondary_region != "" && var.ExcludeAccountIDs != "" ? 1 : 0}"
 236	    provider   = aws.secondary_region
 237	    key        = var.ExcludeAccountIDs
 238	    bucket     = aws_s3_bucket.AHA-S3Bucket-SecondaryRegion[0].bucket
 239	    source     = var.ExcludeAccountIDs
 240	    tags = {
 241	      Name        = "${var.ExcludeAccountIDs}"
 242	    }
 243	}
 244	
 245	# DynamoDB table - Create if secondary region not set
 246	resource "aws_dynamodb_table" "AHA-DynamoDBTable" {
 247	    count = "${var.aha_secondary_region == "" ? 1 : 0}"
 248	    billing_mode   = "PROVISIONED"
 249	    hash_key       = "arn"
 250	    name           = "${var.dynamodbtable}-${random_string.resource_code.result}"
 251	    read_capacity  = 5
 252	    write_capacity = 5
 253	    stream_enabled = false
 254	    tags           = {
 255	       Name   = "${var.dynamodbtable}"
 256	    }
 257	
 258	    attribute {
 259	        name = "arn"
 260	        type = "S"
 261	    }
 262	
 263	    point_in_time_recovery {
 264	        enabled = false
 265	    }
 266	
 267	    timeouts {}
 268	
 269	    ttl {
 270	        attribute_name = "ttl"
 271	        enabled        = true
 272	    }
 273	}
 274	
 275	# DynamoDB table - Multi region Global Table - Create if secondary region is set
 276	resource "aws_dynamodb_table" "AHA-GlobalDynamoDBTable" {
 277	    count = "${var.aha_secondary_region == "" ? 0 : 1}"
 278	    billing_mode     = "PAY_PER_REQUEST"
 279	    hash_key         = "arn"
 280	    name             = "${var.dynamodbtable}-${random_string.resource_code.result}"
 281	    stream_enabled   = true
 282	    stream_view_type = "NEW_AND_OLD_IMAGES"
 283	    tags           = {
 284	       Name   = "${var.dynamodbtable}"
 285	    }
 286	
 287	    attribute {
 288	        name = "arn"
 289	        type = "S"
 290	    }
 291	
 292	    point_in_time_recovery {
 293	        enabled = false
 294	    }
 295	
 296	    replica {
 297	        region_name = var.aha_secondary_region
 298	    }
 299	
 300	    timeouts {}
 301	
 302	    ttl {
 303	        attribute_name = "ttl"
 304	        enabled        = true
 305	    }
 306	}
 307	# Tags for DynamoDB - secondary region
 308	resource "aws_dynamodb_tag" "AHA-GlobalDynamoDBTable" {
 309	    count = "${var.aha_secondary_region == "" ? 0 : 1}"
 310	    provider   = aws.secondary_region
 311	    resource_arn = replace(aws_dynamodb_table.AHA-GlobalDynamoDBTable[count.index].arn, var.aha_primary_region, var.aha_secondary_region)
 312	    key          = "Name"
 313	    value        = "${var.dynamodbtable}"
 314	}
 315	# Tags for DynamoDB - secondary region - default_tags
 316	resource "aws_dynamodb_tag" "AHA-GlobalDynamoDBTable-Additional-tags" {
 317	    for_each = { for key, value in var.default_tags : key => value if var.aha_secondary_region != "" }
 318	    provider   = aws.secondary_region
 319	    resource_arn = replace(aws_dynamodb_table.AHA-GlobalDynamoDBTable[0].arn, var.aha_primary_region, var.aha_secondary_region)
 320	    key          = each.key
 321	    value        = each.value
 322	}
 323	
 324	# Secrets - SlackChannelSecret
 325	resource "aws_secretsmanager_secret" "SlackChannelID" {
 326	    count = "${var.SlackWebhookURL == "" ? 0 : 1}"
 327	    name             = "SlackChannelID"
 328	    description      = "Slack Channel ID Secret"
 329	    recovery_window_in_days      = 0
 330	    tags             = {
 331	        "HealthCheckSlack" = "ChannelID"
 332	    }
 333	    dynamic "replica" {
 334	      for_each = var.aha_secondary_region == "" ? [] : [1]
 335	      content {
 336	        region = var.aha_secondary_region
 337	      }
 338	    }
 339	}
 340	resource "aws_secretsmanager_secret_version" "SlackChannelID" {
 341	    count = "${var.SlackWebhookURL == "" ? 0 : 1}"
 342	    secret_id     = "${aws_secretsmanager_secret.SlackChannelID.*.id[count.index]}"
 343	    secret_string = "${var.SlackWebhookURL}"
 344	}
 345	
 346	# Secrets - MicrosoftChannelSecret
 347	resource "aws_secretsmanager_secret" "MicrosoftChannelID" {
 348	    count = "${var.MicrosoftTeamsWebhookURL == "" ? 0 : 1}"
 349	    name             = "MicrosoftChannelID"
 350	    description      = "Microsoft Channel ID Secret"
 351	    recovery_window_in_days      = 0
 352	    tags             = {
 353	        "HealthCheckMicrosoft" = "ChannelID"
 354	        "Name"                 = "AHA-MicrosoftChannelID"
 355	    }
 356	    dynamic "replica" {
 357	      for_each = var.aha_secondary_region == "" ? [] : [1]
 358	      content {
 359	        region = var.aha_secondary_region
 360	      }
 361	    }
 362	}
 363	resource "aws_secretsmanager_secret_version" "MicrosoftChannelID" {
 364	    count = "${var.MicrosoftTeamsWebhookURL == "" ? 0 : 1}"
 365	    secret_id     = "${aws_secretsmanager_secret.MicrosoftChannelID.*.id[count.index]}"
 366	    secret_string = "${var.MicrosoftTeamsWebhookURL}"
 367	}
 368	
 369	# Secrets - EventBusNameSecret
 370	resource "aws_secretsmanager_secret" "EventBusName" {
 371	    count = "${var.EventBusName == "" ? 0 : 1}"
 372	    name             = "EventBusName"
 373	    description      = "EventBus Name Secret"
 374	    recovery_window_in_days      = 0
 375	    tags             = {
 376	        "EventBusName" = "ChannelID"
 377	        "Name"         = "AHA-EventBusName"
 378	    }
 379	    dynamic "replica" {
 380	      for_each = var.aha_secondary_region == "" ? [] : [1]
 381	      content {
 382	        region = var.aha_secondary_region
 383	      }
 384	    }
 385	}
 386	
 387	resource "aws_secretsmanager_secret_version" "EventBusName" {
 388	    count = "${var.EventBusName == "" ? 0 : 1}"
 389	    secret_id     = "${aws_secretsmanager_secret.EventBusName.*.id[count.index]}"
 390	    secret_string = "${var.EventBusName}"
 391	}
 392	
 393	# Secrets - ChimeChannelSecret
 394	resource "aws_secretsmanager_secret" "ChimeChannelID" {
 395	    count = "${var.AmazonChimeWebhookURL == "" ? 0 : 1}"
 396	    name             = "ChimeChannelID"
 397	    description      = "Chime Channel ID Secret"
 398	    recovery_window_in_days      = 0
 399	    tags             = {
 400	        "HealthCheckChime" = "ChannelID"
 401	        "Name"             = "AHA-ChimeChannelID-${random_string.resource_code.result}"
 402	    }
 403	    dynamic "replica" {
 404	      for_each = var.aha_secondary_region == "" ? [] : [1]
 405	      content {
 406	        region = var.aha_secondary_region
 407	      }
 408	    }
 409	}
 410	resource "aws_secretsmanager_secret_version" "ChimeChannelID" {
 411	    count = "${var.AmazonChimeWebhookURL == "" ? 0 : 1}"
 412	    secret_id     = "${aws_secretsmanager_secret.ChimeChannelID.*.id[count.index]}"
 413	    secret_string = "${var.AmazonChimeWebhookURL}"
 414	}
 415	
 416	# Secrets - AssumeRoleSecret
 417	resource "aws_secretsmanager_secret" "AssumeRoleArn" {
 418	    count = "${var.ManagementAccountRoleArn == "" ? 0 : 1}"
 419	    name             = "AssumeRoleArn"
 420	    description      = "Management account role for AHA to assume"
 421	    recovery_window_in_days      = 0
 422	    tags             = {
 423	        "AssumeRoleArn" = ""
 424	        "Name"          = "AHA-AssumeRoleArn"
 425	    }
 426	    dynamic "replica" {
 427	      for_each = var.aha_secondary_region == "" ? [] : [1]
 428	      content {
 429	        region = var.aha_secondary_region
 430	      }
 431	    }
 432	}
 433	resource "aws_secretsmanager_secret_version" "AssumeRoleArn" {
 434	    count = "${var.ManagementAccountRoleArn == "" ? 0 : 1}"
 435	    secret_id     = "${aws_secretsmanager_secret.AssumeRoleArn.*.id[count.index]}"
 436	    secret_string = "${var.ManagementAccountRoleArn}"
 437	}
