 439	# IAM Role for Lambda function execution
 440	resource "aws_iam_role" "AHA-LambdaExecutionRole" {
 441	    name                  = "AHA-LambdaExecutionRole-${random_string.resource_code.result}"
 442	    path                  = "/"
 443	    assume_role_policy    = jsonencode(
 444	        {
 445	            Version   = "2012-10-17"
 446	            Statement = [
 447	                {
 448	                    Action    = "sts:AssumeRole"
 449	                    Effect    = "Allow"
 450	                    Principal = {
 451	                        Service = "lambda.amazonaws.com"
 452	                    }
 453	                },
 454	            ]
 455	        }
 456	    )
 457	    inline_policy {
 458	        name   = "AHA-LambdaPolicy"
 459	        policy = data.aws_iam_policy_document.AHA-LambdaPolicy-Document.json
 460	    }
 461	    tags             = {
 462	        "Name"             = "AHA-LambdaExecutionRole"
 463	    }
 464	}
 465	
 466	data "aws_iam_policy_document" "AHA-LambdaPolicy-Document" {
 467	  version   = "2012-10-17"
 468	  statement {
 469	    effect = "Allow"
 470	    actions = [
 471	          "logs:CreateLogGroup",
 472	          "logs:CreateLogStream",
 473	          "logs:PutLogEvents",
 474	    ]
 475	    resources = [
 476	          "arn:aws:logs:${var.aha_primary_region}:${data.aws_caller_identity.current.account_id}:*",
 477	          "arn:aws:logs:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:*"
 478	    ]
 479	  }
 480	  statement {
 481	    effect   = "Allow"
 482	    actions   = [
 483	          "health:DescribeAffectedAccountsForOrganization",
 484	          "health:DescribeAffectedEntitiesForOrganization",
 485	          "health:DescribeEventDetailsForOrganization",
 486	          "health:DescribeEventsForOrganization",
 487	          "health:DescribeEventDetails",
 488	          "health:DescribeEvents",
 489	          "health:DescribeEventTypes",
 490	          "health:DescribeAffectedEntities",
 491	          "organizations:ListAccounts",
 492	          "organizations:DescribeAccount",
 493	    ]
 494	    resources = [ "*" ]
 495	  }
 496	  statement {
 497	    effect   = "Allow"
 498	    actions   = [
 499	          "dynamodb:ListTables",
 500	    ]
 501	    resources = [
 502	          "arn:aws:dynamodb:${var.aha_primary_region}:${data.aws_caller_identity.current.account_id}:*",
 503	          "arn:aws:dynamodb:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:*",
 504	    ]
 505	  }
 506	  statement {
 507	    effect   = "Allow"
 508	    actions   = [
 509	          "ses:SendEmail",
 510	    ]
 511	    resources = [
 512	          "arn:aws:ses:${var.aha_primary_region}:${data.aws_caller_identity.current.account_id}:*",
 513	          "arn:aws:ses:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:*",
 514	    ]
 515	  }
 516	  statement {
 517	    effect   = "Allow"
 518	    actions   = [
 519	          "dynamodb:UpdateTimeToLive",
 520	          "dynamodb:PutItem",
 521	          "dynamodb:DeleteItem",
 522	          "dynamodb:GetItem",
 523	          "dynamodb:Scan",
 524	          "dynamodb:Query",
 525	          "dynamodb:UpdateItem",
 526	          "dynamodb:UpdateTable",
 527	          "dynamodb:GetRecords",
 528	    ]
 529	    resources = [
 530	          #aws_dynamodb_table.AHA-DynamoDBTable.arn
 531	          "arn:aws:dynamodb:${var.aha_primary_region}:${data.aws_caller_identity.current.account_id}:table/${var.dynamodbtable}-${random_string.resource_code.result}",
 532	          "arn:aws:dynamodb:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:table/${var.dynamodbtable}-${random_string.resource_code.result}",
 533	    ]
 534	  }
 535	  dynamic "statement" {
 536	    for_each = var.SlackWebhookURL == "" ? [] : [1]
 537	    content {
 538	      effect = "Allow"
 539	      actions = [
 540	          "secretsmanager:GetResourcePolicy",
 541	          "secretsmanager:DescribeSecret",
 542	          "secretsmanager:ListSecretVersionIds",
 543	          "secretsmanager:GetSecretValue",
 544	      ]
 545	      resources = [
 546	          aws_secretsmanager_secret.SlackChannelID[0].arn,
 547	          "arn:aws:secretsmanager:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:secret:${element(split(":", aws_secretsmanager_secret.SlackChannelID[0].arn),6)}"
 548	#          var.aha_secondary_region != "" ? "arn:aws:secretsmanager:${var.aha_secondary_region}:${data.aws_caller_identity.current.account_id}:secret:${element(split(":", aws_secretsmanager_secret.SlackChannelID[0].arn),6)}" : null
 549	      ]
 550	    }
 551	  }
 552	  dynamic "statement" {
 553	    for_each = var.MicrosoftTeamsWebhookURL == "" ? [] : [1]
 554	    content {
 555	      effect = "Allow"
 556	      actions = [
 557	          "secretsmanager:GetResourcePolicy",
 558	          "secretsmanager:DescribeSecret",
 559	          "secretsmanager:ListSecretVersionIds",
 560	          "secretsmanager:GetSecretValue",
 561	      ]
 562	      resources = [
 563	          aws_secretsmanager_secret.MicrosoftChannelID[0].arn,
 564	          "arn:aws:secretsmanager:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:secret:${element(split(":", aws_secretsmanager_secret.MicrosoftChannelID[0].arn),6)}"
 565	      ]
 566	    }
 567	  }
 568	  dynamic "statement" {
 569	    for_each = var.AmazonChimeWebhookURL == "" ? [] : [1]
 570	    content {
 571	      effect = "Allow"
 572	      actions = [
 573	          "secretsmanager:GetResourcePolicy",
 574	          "secretsmanager:DescribeSecret",
 575	          "secretsmanager:ListSecretVersionIds",
 576	          "secretsmanager:GetSecretValue",
 577	      ]
 578	      resources = [
 579	          aws_secretsmanager_secret.ChimeChannelID[0].arn,
 580	          "arn:aws:secretsmanager:${local.secondary_region}:${data.aws_caller_identity.current.account_id}:secret:${element(split(":", aws_secretsmanager_secret.ChimeChannelID[0].arn),6)}"
 581	      ]
 582	    }
