 281	    slack_message = message
 282	    req = Request(
 283	        webhookurl,
 284	        data=json.dumps(slack_message).encode("utf-8"),
 285	        headers={"content-type": "application/json"},
 286	    )
 287	    try:
 288	        response = urlopen(req)
 289	        response.read()
 290	    except HTTPError as e:
 291	        print("Request failed : ", e.code, e.reason)
 292	    except URLError as e:
 293	        print("Server connection failed: ", e.reason, e.reason)
