 415	# get the array of affected entities for all affected accounts and return as an array of JSON objects
 416	def get_affected_entities(health_client, event_arn, affected_accounts, is_org_mode):
 417	    affected_entity_array = []
 418	
 419	    for account in affected_accounts:
 420	        account_name = ""
 421	        if is_org_mode:
 422	            event_entities_paginator = health_client.get_paginator(
 423	                "describe_affected_entities_for_organization"
 424	            )
 425	            event_entities_page_iterator = event_entities_paginator.paginate(
 426	                organizationEntityFilters=[
 427	                    {"awsAccountId": account, "eventArn": event_arn}
 428	                ]
 429	            )
 430	            account_name = get_account_name(account)
 431	        else:
 432	            event_entities_paginator = health_client.get_paginator(
 433	                "describe_affected_entities"
 434	            )
 435	            event_entities_page_iterator = event_entities_paginator.paginate(
 436	                filter={"eventArns": [event_arn]}
 437	            )
 438	
 439	        for event_entities_page in event_entities_page_iterator:
 440	            json_event_entities = json.dumps(event_entities_page, default=myconverter)
 441	            parsed_event_entities = json.loads(json_event_entities)
 442	            for entity in parsed_event_entities["entities"]:
 443	                entity.pop(
 444	                    "entityArn"
 445	                )  # remove entityArn to avoid confusion with the arn of the entityValue (not present)
 446	                entity.pop("eventArn")  # remove eventArn duplicate of detail.arn
 447	                entity.pop("lastUpdatedTime")  # remove for brevity
 448	                if is_org_mode:
 449	                    entity["awsAccountName"] = account_name
 450	                affected_entity_array.append(entity)
 451	
 452	    return affected_entity_array
