 456	# get the entityValues from the array and return as an array (of strings) for use with chat channels
 457	# don't list entities which are accounts (handled separately for chat applications)
 458	def get_resources_from_entities(affected_entity_array):
 459	    resources = []
 460	
 461	    for entity in affected_entity_array:
 462	        if entity["entityValue"] == "UNKNOWN":
 463	            # UNKNOWN indicates a public/non-accountspecific event, no resources
 464	            pass
 465	        elif (
 466	            entity["entityValue"] != "AWS_ACCOUNT"
 467	            and entity["entityValue"] != entity["awsAccountId"]
 468	        ):
 469	            resources.append(entity["entityValue"])
 470	    return resources
