 474	def update_org_ddb(
 475	    event_arn,
 476	    str_update,
 477	    status_code,
 478	    event_details,
 479	    affected_org_accounts,
 480	    affected_org_entities,
 481	):
 482	    # open dynamoDB
 483	    dynamodb = aws_api.resource("dynamodb")
 484	    ddb_table = os.environ["DYNAMODB_TABLE"]
 485	    aha_ddb_table = dynamodb.Table(ddb_table)
 486	    event_latestDescription = event_details["successfulSet"][0]["eventDescription"][
 487	        "latestDescription"
 488	    ]
 489	    # set time parameters
 490	    delta_hours = os.environ["EVENT_SEARCH_BACK"]
 491	    delta_hours = int(delta_hours)
 492	    delta_hours_sec = delta_hours * 3600
 493	
 494	    # formatting time in seconds
 495	    srt_ddb_format_full = "%Y-%m-%d %H:%M:%S"
 496	    str_ddb_format_sec = "%s"
 497	    sec_now = datetime.strftime(datetime.now(), str_ddb_format_sec)
 498	
 499	    # check if event arn already exists
 500	    try:
 501	        response = aha_ddb_table.get_item(Key={"arn": event_arn})
 502	    except ClientError as e:
 503	        print(e.response["Error"]["Message"])
 504	    else:
 505	        is_item_response = response.get("Item")
 506	        if is_item_response == None:
 507	            print(datetime.now().strftime(srt_ddb_format_full) + ": record not found")
 508	            # write to dynamodb
 509	            response = aha_ddb_table.put_item(
 510	                Item={
 511	                    "arn": event_arn,
 512	                    "lastUpdatedTime": str_update,
 513	                    "added": sec_now,
 514	                    "ttl": int(sec_now) + delta_hours_sec + 86400,
 515	                    "statusCode": status_code,
 516	                    "affectedAccountIDs": affected_org_accounts,
 517	                    "latestDescription": event_latestDescription
 518	                    # Cleanup: DynamoDB entry deleted 24 hours after last update
 519	                }
 520	            )
 521	            affected_org_accounts_details = [
 522	                f"{get_account_name(account_id)} ({account_id})"
 523	                for account_id in affected_org_accounts
 524	            ]
 525	            # send to configured endpoints
 526	            if status_code != "closed":
 527	                send_org_alert(
 528	                    event_details,
 529	                    affected_org_accounts_details,
 530	                    affected_org_entities,
 531	                    event_type="create",
 532	                )
 533	            else:
 534	                send_org_alert(
 535	                    event_details,
 536	                    affected_org_accounts_details,
 537	                    affected_org_entities,
 538	                    event_type="resolve",
 539	                )
 540	
 541	        else:
 542	            item = response["Item"]
 543	            if item["lastUpdatedTime"] != str_update and (
 544	                item["statusCode"] != status_code
 545	                or item["latestDescription"] != event_latestDescription
 546	                or item["affectedAccountIDs"] != affected_org_accounts
 547	            ):
 548	                print(
 549	                    datetime.now().strftime(srt_ddb_format_full)
 550	                    + ": last Update is different"
 551	                )
 552	                # write to dynamodb
 553	                response = aha_ddb_table.put_item(
 554	                    Item={
 555	                        "arn": event_arn,
 556	                        "lastUpdatedTime": str_update,
 557	                        "added": sec_now,
 558	                        "ttl": int(sec_now) + delta_hours_sec + 86400,
 559	                        "statusCode": status_code,
 560	                        "affectedAccountIDs": affected_org_accounts,
 561	                        "latestDescription": event_latestDescription
 562	                        # Cleanup: DynamoDB entry deleted 24 hours after last update
 563	                    }
 564	                )
 565	                affected_org_accounts_details = [
 566	                    f"{get_account_name(account_id)} ({account_id})"
 567	                    for account_id in affected_org_accounts
 568	                ]
 569	                # send to configured endpoints
 570	                if status_code != "closed":
 571	                    send_org_alert(
 572	                        event_details,
 573	                        affected_org_accounts_details,
 574	                        affected_org_entities,
 575	                        event_type="create",
 576	                    )
 577	                else:
 578	                    send_org_alert(
 579	                        event_details,
 580	                        affected_org_accounts_details,
 581	                        affected_org_entities,
 582	                        event_type="resolve",
 583	                    )
 584	            else:
 585	                print("No new updates found, checking again in 1 minute.")
