 737	def get_secret(secret_name, client):
 738	    try:
 739	        get_secret_value_response = client.get_secret_value(SecretId=secret_name)
 740	    except ClientError as e:
 741	        print(f"There was an error with the {secret_name} secret: ", e.response)
 742	        return "None"
 743	    finally:
 744	        if "SecretString" not in get_secret_value_response:
 745	            return "None"
 746	
 747	        return get_secret_value_response["SecretString"]
