 592	def cleanup_time(event_time):
 593	    """
 594	    Takes as input a datetime string as received from The AWS Health event_detail call.  It converts this string to a
 595	    datetime object, changes the timezone to EST and then formats it into a readable string to display in Slack.
 596	
 597	    :param event_time: datetime string
 598	    :type event_time: str
 599	    :return: A formatted string that includes the month, date, year and 12-hour time.
 600	    :rtype: str
 601	    """
 602	    if not event_time:
 603	        return "Unknown"
 604	
 605	    event_time = datetime.strptime(event_time[:16], '%Y-%m-%d %H:%M')
 606	    return event_time.strftime("%Y-%m-%d %H:%M:%S")
