 609	def get_last_aws_update(event_details):
 610	    """
 611	    Takes as input the event_details and returns the last update from AWS (instead of the entire timeline)
 612	
 613	    :param event_details: Detailed information about a specific AWS health event.
 614	    :type event_details: dict
 615	    :return: the last update message from AWS
 616	    :rtype: str
 617	    """
 618	    aws_message = event_details['successfulSet'][0]['eventDescription']['latestDescription']
 619	    return aws_message
